@icontract.ensure(lambda result, tbl, alias_map: (not (not (alias_map and tbl in alias_map) and any(c.isupper() for c in tbl))) or result == "".join([c for c in tbl if c.isupper()]))
@icontract.ensure(lambda result, tbl, alias_map: (not (not (alias_map and tbl in alias_map) and not any(c.isupper() for c in tbl))) or result == "".join([l for l, prev in zip(tbl, "_" + tbl) if prev == "_" and l != "_"]) )
